    size_t old_n_buckets = data->n_buckets;
    size_t new_n_buckets;
    struct sys_hashmap_bucket *new_buckets;
    struct sys_hashmap_bucket *old_buckets = data->buckets;

    // ... (size calculation and overflow checks) ...

    new_buckets = data->alloc_func(old_buckets, new_n_buckets * sizeof(struct sys_hashmap_bucket));

